mapper.select:
SELECT r.*, m.name as memberName, c.name as courseName, c.start_time as courseStartTime, co.name as coachName
FROM reservation r
LEFT JOIN member m ON r.member_id = m.id
LEFT JOIN course c ON r.course_id = c.id
LEFT JOIN coach co ON c.coach_id = co.id


        AND r.member_id = #{memberId}


        AND r.course_id = #{courseId}


        AND r.status = #{status}


ORDER BY r.create_time DESC
